import type { Request, Response } from 'express';

/**
 * Vercel compiles this function only after the project build has completed.
 * The build produces one self-contained application handler next to this
 * entrypoint. Keeping the generated bundle inside `api/` preserves the
 * relative path inside Vercel's function package and lets the tracer include
 * the artifact deterministically.
 */
// @ts-ignore -- api/api-handler.cjs is generated by `bun run build` after typecheck.
import * as bundledModule from './api-handler.cjs';

const candidate = (bundledModule as any).default || bundledModule;
const handler = candidate as (req: Request, res: Response) => unknown;

export default handler;
